// @generated by:gauntlet run:godseye-local-delivery
import { randomUUID } from "node:crypto";
import { ControlPlane } from "@godseye/core";
import { openStore, type Store, schema } from "@godseye/store";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { owner, projectInput, repository, signedDelivery, webhookKey } from "./helpers.js";

function pull(action = "opened") {
  return {
    action,
    number: 42,
    repository: { id: repository.repositoryId, full_name: repository.fullName },
    installation: { id: repository.installationId },
    pull_request: {
      number: 42,
      head: {
        ref: "feature/preview",
        sha: "b".repeat(40),
        repo: { id: repository.repositoryId, full_name: repository.fullName },
      },
      base: { ref: "main", repo: { id: repository.repositoryId, full_name: repository.fullName } },
    },
  };
}
const delivery = (payload: unknown, deliveryId = randomUUID()) =>
  signedDelivery(JSON.stringify(payload, null, 2), { event: "pull_request", deliveryId });

describe("raw authenticated PR intention intake and project fanout", () => {
  let store: Store, core: ControlPlane, projectId: string;
  beforeEach(async () => {
    store = await openStore();
    core = new ControlPlane(store);
    const project = await core.createProject(owner, projectInput, randomUUID());
    projectId = project.id;
    await core.configureRepository(owner, project.id, repository, project.revision, randomUUID());
  });
  afterEach(async () => {
    await store.close();
  });

  it.each(["opened", "synchronize", "reopened", "closed"])(
    "T-AC-44 records a signed %s PR as pending independent verification",
    async (action) => {
      const result = await core.receiveGithubDelivery(delivery(pull(action)), webhookKey);
      expect(result.outcome).toBe("queued");
      expect(await core.listCiRuns(owner)).toEqual([
        expect.objectContaining({
          id: result.runId,
          projectId,
          branch: "feature/preview",
          commitSha: "b".repeat(40),
          trigger: "pull_request",
          status: "pending_verification",
        }),
      ]);
      expect((await store.db.select().from(schema.ciRuns))[0]).toMatchObject({
        repositorySnapshot: repository,
        pullRequestNumber: 42,
        eventAction: action,
      });
      expect(await store.db.select().from(schema.deliveryPreviews)).toEqual([]);
    },
  );
  it("T-AC-44 authenticates pretty-printed PR bytes without trusting reserialized JSON", async () => {
    const valid = delivery(pull());
    await expect(
      core.receiveGithubDelivery(
        { ...valid, rawBody: Buffer.from(JSON.stringify(pull())) },
        webhookKey,
      ),
    ).rejects.toMatchObject({ code: "INVALID_SIGNATURE", status: 401 });
    expect(await core.listCiRuns(owner)).toEqual([]);
    expect((await core.receiveGithubDelivery(valid, webhookKey)).outcome).toBe("queued");
  });
  it("T-AC-44 fans one authenticated PR into each matching shared-repository project exactly once under concurrent retries", async () => {
    const other = await core.createProject(
      owner,
      { ...projectInput, slug: "shared-pr" },
      randomUUID(),
    );
    await core.configureRepository(owner, other.id, repository, other.revision, randomUUID());
    const selected = delivery(pull()),
      results = await Promise.all(
        [0, 1, 2].map(() => core.receiveGithubDelivery(selected, webhookKey)),
      );
    expect(results.filter((result) => result.outcome === "queued")).toHaveLength(1);
    expect(results.filter((result) => result.outcome === "duplicate")).toHaveLength(2);
    expect((await core.listCiRuns(owner)).map((run) => run.projectId).sort()).toEqual(
      [projectId, other.id].sort(),
    );
  });
  it("T-AC-44 rejects reused PR delivery identifiers with different authenticated head or close contents", async () => {
    const id = randomUUID();
    await core.receiveGithubDelivery(delivery(pull(), id), webhookKey);
    await expect(
      core.receiveGithubDelivery(delivery(pull("closed"), id), webhookKey),
    ).rejects.toMatchObject({ code: "DELIVERY_CONFLICT", status: 409 });
    expect(await core.listCiRuns(owner)).toHaveLength(1);
  });
  it.each([
    "fork",
    "missing-head-repository",
    "foreign-base",
    "foreign-base-name",
    "foreign-installation",
    "unbound-base-ref",
    "unsubscribed-action",
    "mismatched-number",
  ])("T-AC-44 ignores a correctly signed %s PR without creating authority", async (mode) => {
    const payload = pull();
    if (mode === "fork") payload.pull_request.head.repo = { id: 999, full_name: "external/fork" };
    if (mode === "missing-head-repository")
      Object.assign(payload.pull_request.head, { repo: null });
    if (mode === "foreign-base") payload.pull_request.base.repo.id = 999;
    if (mode === "foreign-base-name")
      payload.pull_request.base.repo.full_name = "foreign/repository";
    if (mode === "foreign-installation") payload.installation.id = 999;
    if (mode === "unbound-base-ref") payload.pull_request.base.ref = "untracked";
    if (mode === "unsubscribed-action") payload.action = "labeled";
    if (mode === "mismatched-number") payload.pull_request.number = 43;
    expect((await core.receiveGithubDelivery(delivery(payload), webhookKey)).outcome).toBe(
      "ignored",
    );
    expect(await core.listCiRuns(owner)).toEqual([]);
    expect(await store.db.select().from(schema.deliveryPolicies)).toEqual([]);
  });
  it.each(["invalid-sha", "zero-sha", "escaping-ref", "zero-number"])(
    "T-AC-44 rejects malformed PR %s with no accepted intention",
    async (mode) => {
      const payload = pull();
      if (mode === "invalid-sha") payload.pull_request.head.sha = "not-a-commit";
      if (mode === "zero-sha") payload.pull_request.head.sha = "0".repeat(40);
      if (mode === "escaping-ref") payload.pull_request.head.ref = "../production";
      if (mode === "zero-number") payload.number = 0;
      await expect(core.receiveGithubDelivery(delivery(payload), webhookKey)).rejects.toMatchObject(
        { code: "INVALID_DELIVERY", status: 400 },
      );
      expect(await core.listCiRuns(owner)).toEqual([]);
    },
  );
});
